def main():
	(n, m, h) = map(int, input().split(' '))
	layers = []
	for i in range(h):
		layers.append(list(map(int, input().split(' '))))
	cellsRem = n * m
	cost = 0
	for i in sorted(list(layers), key=lambda x: x[1]):
		if cellsRem > i[0]:
			cost += i[0] * i[1]
			cellsRem -= i[0]
		else:
			cost += cellsRem * i[1]
			cellsRem = 0
			break
	if cellsRem > 0:
		print('Impossible')
	else:
		print(cost)
main()
